fn bitwise_and(a: Vec<u8>, b: Vec<u8>) -> Vec<u8> {
    // Since a and b have the same length, we can iterate by index safely
    let mut result = Vec::with_capacity(a.len());
    for i in 0..a.len() {
        result.push(a[i] & b[i]);
    }
    result
}